from pathlib import Path
from html import escape
ROOT=Path(__file__).parent

def page(name,title,description,body):
    if name == 'case-studies/assistant-s.html':
        body = body.replace('assets/companion.svg', 'assets/assistant-s-preview.png').replace('Original conceptual illustration of a desktop companion, not a screenshot of the private application.', 'Screenshot of the animated room in Assistant S.')
    if name == 'case-studies/scribevo.html':
        body = body.replace('<h2>', '<figure><img class="diagram" src="../assets/scribevo-preview.png" alt="Prepared Scribevo product example with a reviewable correction"><figcaption>Prepared product example showing how a suggestion is reviewed.</figcaption></figure><h2>', 1)
    prefix='../' if '/' in name else ''
    url='https://slooma951.github.io/portfolio/'+name
    content=f'''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; img-src 'self'; style-src 'self'; script-src 'self'; object-src 'none'; base-uri 'self'; form-action 'none'"><title>{escape(title)} | Salem Elatrash</title><meta name="description" content="{escape(description)}"><link rel="canonical" href="{url}"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(description)}"><meta property="og:image" content="https://slooma951.github.io/portfolio/assets/social.png"><meta property="og:url" content="{url}"><link rel="icon" href="{prefix}favicon.svg"><link rel="stylesheet" href="{prefix}css/home.css"><script src="{prefix}js/theme.js"></script></head><body><main class="reading"><a class="back" href="{prefix}index.html#work">← Back to portfolio</a><p class="eyebrow">Salem Elatrash / {escape(title)}</p><h1>{escape(title)}</h1>{body}</main><footer class="wrap footer"><span>© 2026 Salem Elatrash</span><div><a href="{prefix}privacy.html">Privacy</a><a href="{prefix}terms.html">Terms</a></div></footer></body></html>'''
    (ROOT/name).write_text(content,encoding='utf-8')

def diagram(filename,title,steps):
    elements=[]
    for i,(label,detail) in enumerate(steps):
        y=85+i*100
        elements.append(f'<rect x="35" y="{y}" width="650" height="78" rx="12" fill="white" stroke="#d4dfed"/><circle cx="72" cy="{y+39}" r="20" fill="#e8f0fc"/><text x="72" y="{y+45}" text-anchor="middle" font-size="15" fill="#1768d8">{i+1}</text><text x="112" y="{y+29}" font-size="19" font-weight="bold">{escape(label)}</text><text x="112" y="{y+55}" font-size="14" fill="#596579">{escape(detail)}</text>')
        if i<len(steps)-1:elements.append(f'<path d="M360 {y+81}v16m-5-5 5 5 5-5" stroke="#86a1c7" fill="none" stroke-width="2"/>')
    height=105+len(steps)*100
    svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="720" height="{height}" viewBox="0 0 720 {height}" role="img"><title>{escape(title)}</title><rect width="720" height="{height}" rx="18" fill="#f2f4f7"/><g font-family="Arial,sans-serif" fill="#18202f"><text x="35" y="49" font-size="23" font-weight="bold">{escape(title)}</text>'+''.join(elements)+'</g></svg>'
    (ROOT/'assets'/filename).write_text(svg,encoding='utf-8')

